import React, { useState } from 'react';
import { chatAi } from '../api';
import { useNavigate } from 'react-router-dom';

function prettifyText(text) {
  if (!text) return '';
  // Turn inline bullets into real lines and preserve spacing
  let out = text
    .replace(/\s\*\s+/g, '\n• ')      // convert " * " into a new bullet line
    .replace(/\n\s*\*\s+/g, '\n• ')  // convert line-leading * into •
    .replace(/\s-\s+/g, '\n• ')        // convert " - " into bullet
    .replace(/\n\s*-\s+/g, '\n• ');   // convert line-leading - into •
  return out;
}

export default function AssistantPage() {
  const [messages, setMessages] = useState([
    { role: 'assistant', content: 'Hi! I can suggest projects and recommend your next course. Ask me anything.' },
  ]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [structured, setStructured] = useState(null);
  const navigate = useNavigate();

  async function send() {
    const text = input.trim();
    if (!text) return;
    const next = [...messages, { role: 'user', content: text }];
    setMessages(next);
    setInput('');
    try {
      setSending(true);
      const res = await chatAi(next.map(({ role, content }) => ({ role, content })));
      const reply = (res && res.reply) || 'Sorry, I could not generate a reply.';
      // Save structured payload, if any, for formatted view below
      setStructured(res && res.structured ? res.structured : null);
      setMessages((prev) => [...prev, { role: 'assistant', content: reply }]);
    } catch (e) {
      const msg = e?.data?.detail || e?.message || 'AI request failed';
      setMessages((prev) => [...prev, { role: 'assistant', content: `Error: ${msg}` }]);
    } finally {
      setSending(false);
    }
  }

  function onKey(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  }

  return (
    <div className="pageWrap" style={{ gap: 12 }}>
      <div className="headerWrap">
        <div className="iconBadge">🤖</div>
        <h1 style={{ margin: 8 }}>AI Assistant</h1>
        <p style={{ margin: 0, color: '#667085' }}>
          Ask for project ideas based on your purchases/teaching history or get a next-course recommendation.
        </p>
      </div>

      <div className="card" style={{ maxWidth: 900, width: '100%', display: 'flex', flexDirection: 'column', height: '70vh' }}>
        <div style={{ flex: 1, overflow: 'auto', paddingRight: 6 }}>
          {messages.map((m, idx) => (
            <div key={idx} style={{
              marginBottom: 10,
              textAlign: m.role === 'assistant' ? 'left' : 'right'
            }}>
              <div style={{
                display: 'inline-block',
                background: m.role === 'assistant' ? '#F3F4F6' : '#2563EB',
                color: m.role === 'assistant' ? '#111827' : 'white',
                padding: '8px 12px',
                borderRadius: 10,
                maxWidth: '80%'
              }}>
                {m.role === 'assistant' && structured && idx === messages.length - 1 ? (
                  <span>I prepared structured recommendations below.</span>
                ) : (
                  <span style={{ whiteSpace: 'pre-wrap' }}>{prettifyText(m.content)}</span>
                )}
              </div>
            </div>
          ))}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={onKey}
            placeholder="e.g., Recommend a project based on my recent DBMS purchase"
            style={{ flex: 1, height: 60, resize: 'none' }}
          />
          <button className="btnPrimary" onClick={send} disabled={sending || !input.trim()}>
            {sending ? 'Thinking…' : 'Send'}
          </button>
          <button className="btnSecondary" onClick={() => navigate('/')}>Back</button>
        </div>
      </div>

      {/* Structured panels, if available */}
      {structured && (
        <div className="card" style={{ maxWidth: 900, width: '100%', marginTop: 12 }}>
          {Array.isArray(structured.project_recommendations) && structured.project_recommendations.length > 0 && (
            <div style={{ marginBottom: 16 }}>
              <h3 style={{ marginTop: 0 }}>Project Recommendations</h3>
              <ul>
                {structured.project_recommendations.slice(0, 5).map((p, i) => (
                  <li key={i} style={{ marginBottom: 10 }}>
                    <div style={{ fontWeight: 600 }}>{p.title}</div>
                    {p.why && <div style={{ color: '#6B7280' }}>{p.why}</div>}
                    {Array.isArray(p.steps) && p.steps.length > 0 && (
                      <ol style={{ marginTop: 6 }}>
                        {p.steps.slice(0, 6).map((s, j) => (
                          <li key={j}>{s}</li>
                        ))}
                      </ol>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {Array.isArray(structured.next_course_recommendations) && structured.next_course_recommendations.length > 0 && (
            <div>
              <h3 style={{ marginTop: 0 }}>Next Course Recommendations</h3>
              <ul>
                {structured.next_course_recommendations.slice(0, 5).map((c, i) => (
                  <li key={i} style={{ marginBottom: 8 }}>
                    <div>
                      <span style={{ fontWeight: 600 }}>{c.title}</span>
                      {typeof c.points === 'number' && <span style={{ marginLeft: 8, color: '#6B7280' }}>• {c.points} pts</span>}
                      {c.id ? <span style={{ marginLeft: 8, color: '#9CA3AF' }}>id: {c.id}</span> : null}
                    </div>
                    {c.why && <div style={{ color: '#6B7280' }}>{c.why}</div>}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {structured.answer && (
            <div style={{ marginTop: 12 }}>
              <h3 style={{ marginTop: 0 }}>Answer</h3>
              <div style={{ whiteSpace: 'pre-wrap' }}>{prettifyText(structured.answer)}</div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
